URL = _root.QuizReport_URL + "?" + "&Student_ID=" + _root.Student_ID + "&Class_ID=" + _root.Class_ID + "&Lesson_ID=" + _root.Lesson_ID + "&Right=" + _global.CorAns + "&Wrong=" + _global.WrongAns + "&TimeTaken=" + _global.timeTaken + "&REVIEWANS=" + _global.REVIEWANS;
