   {
      _root.animation_mc.animation.Mc_Quiz_Audio._alpha = 100;
      _root.animation_mc.animation.Mc_Quiz_Audio.gotoAndStop(5);
   }
   else
   {
      _root.animation_mc.animation.Mc_Quiz_Audio._alpha = 100;
      _root.animation_mc.animation.Mc_Quiz_Audio.gotoAndStop(6);
   }
   if(_root.dtfFinalQuizAnswerAudio.text.toUpperCase() == "OFF")
   {
      i = 1;
      while(i <= 4)
      {
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i)._visible = false;
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i).gotoAndStop(8);
         i++;
      }
   }
   else
   {
      i = 1;
      while(i <= 4)
      {
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i)._alpha = 100;
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i)._visible = true;
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i).gotoAndStop(6);
         i++;
      }
   }
