   {
      i = 1;
      while(i <= 4)
      {
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i)._alpha = 100;
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i).gotoAndStop(5);
         i++;
      }
   }
   else
   {
      i = 1;
      while(i <= 4)
      {
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i)._alpha = 100;
         eval("_root.animation_mc.animation.Mc_Quiz_Audio_" + i).gotoAndStop(6);
         i++;
      }
   }
   delete onEnterFrame;
};
this.onLoad();

function doGetRandomQuiz()
{
   _global.totQuizCount++;
   if(_global.totQuizCount > parseInt(_global.totalQuestionsCount))
   {
      if(_global.arrayResponseAnswer.length >= parseInt(_global.totalQuestionsCount))
      {
         i = 1;
         while(i <= 4)
         {
            eval("A" + _global.qLabelName.substring(1,_global.qLabelName.length) + "Opt" + i).enabled = false;
            i++;
         }
      }
      Mc_Finish._visible = true;
      Mc_Finish.gotoAndStop(2);
   }
   else if(_global.quizLabelArray.length >= 1)
   {
      _global.tempQNo = random(_global.quizLabelArray.length);
      _global.qLabelName = _global.quizLabelArray[_global.tempQNo];
      _global.arrayReview.push(_global.revLabelArray[_global.tempQNo]);
      _global.quizLabelArray.splice(_global.tempQNo,1);
      _global.revLabelArray.splice(_global.tempQNo,1);
      _global.quizSection = true;
      gotoAndStop(_global.qLabelName);
      doPutQNo();
   }
}
function doPutQNo()
{
   if(_global.totQuizCount.toString().length == 1)
   {
      QuestNo.text = "  " + _global.totQuizCount.toString() + ".";
   }
   else
   {
      QuestNo.text = _global.totQuizCount.toString() + ".";
   }
   if(_global.totQuizCount.toString().length == 1)
   {
      CQ.text = "  " + _global.totQuizCount.toString();
   }
   else
   {
      CQ.text = _global.totQuizCount.toString();
   }
   TQ.text = _global.totalQuestionsCount;
}
function doGetReview()
{
   _global.reviewCount = _global.reviewCount + 1;
   if(_global.arrayReview.length >= 1)
   {
      _global.quizSection = true;
      gotoAndStop(_global.arrayReview[_global.reviewCount - 1]);
      doPutRNo();
      doShowReview();
   }
   if(_global.reviewCount == parseInt(_global.totalQuestionsCount))
   {
      Mc_Result._visible = true;
      Mc_Result.gotoAndStop(1);
   }
   else if(_global.reviewCount > parseInt(_global.totalQuestionsCount))
   {
      _root.animation_mc.unloadMovie();
      _root.animation_mc_preload.unloadMovie();
      if(_root.Report_URL == "" || _root.Report_URL == "undefined" || _root.Report_URL == undefined)
      {
         _root.setBookMark();
         _root.doCloseApp();
      }
      else
      {
         _global.closeApp = "yes";
         URL = _root.Report_URL + "?" + "&Student_ID=" + _root.Student_ID + "&Class_ID=" + _root.Class_ID + "&Lesson_ID=" + _root.Lesson_ID + "&Section=" + _global.Section + "&FileName=" + _global.FileName + "&Failure=" + _global.Failure + "&Close=" + _global.closeApp + "&Download_Time=" + dtfTIMETAKEN1.text;
         _global.BmId = _global.splitStart + "SPLDATA" + _global.splitEnd + "SPLDATA" + _global.sectionNumber + "SPLDATA" + _global.slideNumber + "SPLDATA" + _global.playSwfFileName;
         URL = URL + "&Bookmark_URL=" + _global.BmId;
         strURL = URL;
         getURL(strURL,"");
      }
   }
}
function doPutRNo()
{
   tempRevCount = _global.reviewCount;
   if(tempRevCount.toString().length == 1)
   {
      QuestNo.text = "  " + tempRevCount.toString() + ".";
   }
   else
   {
      QuestNo.text = tempRevCount.toString() + ".";
   }
   if(tempRevCount.toString().length == 1)
   {
      CQ.text = "  " + tempRevCount.toString();
   }
   else
   {
      CQ.text = tempRevCount.toString();
   }
   TQ.text = _global.totalQuestionsCount;
}
function doShowReview()
{
   i = 1;
   while(i <= 4)
   {
      eval("TxtFeed" + i).text = "";
      i++;
   }
   var §mcName:String§;
   var §fldName:Object§;
   var §startPos:Number§;
   var §endPos:Number§;
   tempAnsPos = parseInt(_global.arrayReview[_global.reviewCount - 1].substring(1,_global.arrayReview[_global.reviewCount - 1].length));
   mcName = "R" + _global.arrayResponseAnswer[_global.reviewCount - 1].substring(1,_global.arrayResponseAnswer[_global.reviewCount - 1].length);
   i = 0;
   while(i < _global.arrayResponseAnswer[_global.reviewCount - 1].length)
   {
      if(_global.arrayResponseAnswer[_global.reviewCount - 1].charAt(i) == "t")
      {
         startPos = i;
      }
      i++;
   }
   endPos = _global.arrayResponseAnswer[_global.reviewCount - 1].length;
   fldName = eval("TxtFeed" + _global.arrayResponseAnswer[_global.reviewCount - 1].substring(startPos + 1,endPos));
   if(_global.arrayResponseAnswer[_global.reviewCount - 1] == _global.arrayAnswer[_global.reviewCount - 1])
   {
      var §colorObj:Object§;
      var §myColor:Color§;
      var colorObj = mcName;
      myColor = new Color(colorObj);
      myColor.setRGB(39270);
      fldName.textColor = 39270;
      fldName.text = "Correct";
      fldName.border = 1;
      fldName.borderColor = 39270;
   }
   else
   {
      var §colorObj:Object§;
      var §myColor:Color§;
      var colorObj = mcName;
      var myColor = new Color(colorObj);
      myColor.setRGB(16711680);
      fldName.textColor = 16711680;
      fldName.text = "Incorrect";
      fldName.border = 1;
      fldName.borderColor = 16711680;
   }
   mcName = "R" + _global.arrayAnswer[tempAnsPos - 1].substring(1,_global.arrayAnswer[tempAnsPos - 1].length);
   colorObj = mcName;
   myColor = new Color(colorObj);
   myColor.setRGB(39270);
   i = 0;
   while(i < _global.arrayAnswer[tempAnsPos - 1].length)
   {
      if(_global.arrayAnswer[tempAnsPos - 1].charAt(i) == "t")
      {
         startPos = i;
      }
      i++;
   }
   endPos = _global.arrayAnswer[tempAnsPos - 1].length;
   fldName = eval("TxtFeed" + _global.arrayAnswer[tempAnsPos - 1].substring(startPos + 1,endPos));
   fldName.textColor = 39270;
   fldName.text = "Correct";
   fldName.border = 1;
   fldName.borderColor = 39270;
   if(_global.arrayResponseAnswer[_global.reviewCount - 1].substring(_global.arrayResponseAnswer[_global.reviewCount - 1].length - 1,_global.arrayResponseAnswer[_global.reviewCount - 1].length) == "1")
   {
      txtResAns.text = "A";
   }
   if(_global.arrayResponseAnswer[_global.reviewCount - 1].substring(_global.arrayResponseAnswer[_global.reviewCount - 1].length - 1,_global.arrayResponseAnswer[_global.reviewCount - 1].length) == "2")
   {
      txtResAns.text = "B";
   }
   if(_global.arrayResponseAnswer[_global.reviewCount - 1].substring(_global.arrayResponseAnswer[_global.reviewCount - 1].length - 1,_global.arrayResponseAnswer[_global.reviewCount - 1].length) == "3")
   {
      txtResAns.text = "C";
   }
   if(_global.arrayResponseAnswer[_global.reviewCount - 1].substring(_global.arrayResponseAnswer[_global.reviewCount - 1].length - 1,_global.arrayResponseAnswer[_global.reviewCount - 1].length) == "4")
   {
      txtResAns.text = "D";
   }
   if(_global.arrayAnswer[tempAnsPos - 1].substring(startPos + 1,endPos) == "1")
   {
      txtCorAns.text = "A";
   }
   if(_global.arrayAnswer[tempAnsPos - 1].substring(startPos + 1,endPos) == "2")
   {
      txtCorAns.text = "B";
   }
   if(_global.arrayAnswer[tempAnsPos - 1].substring(startPos + 1,endPos) == "3")
   {
      txtCorAns.text = "C";
   }
   if(_global.arrayAnswer[tempAnsPos - 1].substring(startPos + 1,endPos) == "4")
   {
      txtCorAns.text = "D";
   }
   if(_global.arrayResponseAnswer[_global.reviewCount - 1].substring(_global.arrayResponseAnswer[_global.reviewCount - 1].length - 1,_global.arrayResponseAnswer[_global.reviewCount - 1].length) == _global.arrayAnswer[tempAnsPos - 1].substring(startPos + 1,endPos))
   {
      txtResAns.textColor = 39270;
   }
   else
   {
      txtResAns.textColor = 16711680;
   }
   txtCorAns.textColor = 39270;
}
Mc_Result._visible = false;
Mc_Finish._visible = false;
Mc_Finish.gotoAndStop(1);
